    loadBlock(argon2HashLong(concatBytes(h0, argon2Le32(0), argon2Le32(lane)), 1024), lane * laneLen);
    loadBlock(argon2HashLong(concatBytes(h0, argon2Le32(1), argon2Le32(lane)), 1024), lane * laneLen + 1);
