// WebCrypto primitives: HMAC-SHA-256, HKDF32, SIV (SPEC.md section 1)
// ---------------------------------------------------------------------------------------

const subtle: SubtleCrypto = globalThis.crypto.subtle;

function randomBytes(n: number): Bytes {
  const out = new Uint8Array(n);
  globalThis.crypto.getRandomValues(out);
  return out;
}

async function sha256(data: Uint8Array): Promise<Bytes> {
  return new Uint8Array(await subtle.digest("SHA-256", data as BufferSource));
}

async function sha512(data: Uint8Array): Promise<Bytes> {
  return new Uint8Array(await subtle.digest("SHA-512", data as BufferSource));
}

async function importHmacKey(key: Uint8Array): Promise<CryptoKey> {
  return subtle.importKey("raw", key as BufferSource, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
}

async function hmacSha256(key: Uint8Array, data: Uint8Array): Promise<Bytes> {
  return new Uint8Array(await subtle.sign("HMAC", await importHmacKey(key), data as BufferSource));
}

const ZERO32: Bytes = new Uint8Array(32);

/** HKDF-SHA-256 with a 32-byte output; salt null means 32 zero bytes. */
async function hkdf32(ikm: Uint8Array, salt: Uint8Array | null, info: string): Promise<Bytes> {
  const prk = await hmacSha256(salt ?? ZERO32, ikm);
  return hmacSha256(prk, concatBytes(utf8(info), new Uint8Array([1])));
}

type SivKey = { mac: CryptoKey; enc: CryptoKey };

async function sivKey(parent: Uint8Array, purpose: string): Promise<SivKey> {
  const macRaw = await hkdf32(parent, null, "ssenc1/" + purpose + "-mac");
  const encRaw = await hkdf32(parent, null, "ssenc1/" + purpose + "-enc");
  return {
    mac: await importHmacKey(macRaw),
    enc: await subtle.importKey("raw", encRaw as BufferSource, { name: "AES-CTR" }, false, ["encrypt", "decrypt"]),
  };
}

async function sivTag(key: SivKey, ad: Uint8Array, pt: Uint8Array): Promise<Bytes> {
  const full = await subtle.sign("HMAC", key.mac, concatBytes(u64be(ad.length), ad, pt) as BufferSource);
  return new Uint8Array(full.slice(0, 16));
}

function sivIv(tag: Uint8Array): Bytes {
  const iv = new Uint8Array(16);
  iv.set(tag);
  iv[8] &= 0x7f;
  iv[12] &= 0x7f;
  return iv;
}

async function sivEncrypt(key: SivKey, ad: Uint8Array, pt: Uint8Array): Promise<Bytes> {
  const tag = await sivTag(key, ad, pt);
  const ct = await subtle.encrypt({ name: "AES-CTR", counter: sivIv(tag), length: 64 }, key.enc, pt as BufferSource);
  return concatBytes(tag, new Uint8Array(ct));
}

async function sivDecrypt(key: SivKey, ad: Uint8Array, input: Uint8Array): Promise<Bytes> {
  if (input.length < 16) throw new SsencError("MALFORMED", "ciphertext shorter than the authentication tag");
  const tag = input.subarray(0, 16);
  const pt = new Uint8Array(await subtle.decrypt(
    { name: "AES-CTR", counter: sivIv(tag), length: 64 }, key.enc, input.subarray(16) as BufferSource));
  if (!constantTimeEqual(tag, await sivTag(key, ad, pt))) {
    throw new SsencError("AUTH", "authentication failed (wrong key or modified data)");
  }
  return pt;
}


// ---------------------------------------------------------------------------------------
// header parsing and serialising (SPEC.md section 2)
// ---------------------------------------------------------------------------------------

type KdfParams = { m: number; t: number; p: number };

type PwSlot = { type: "pw"; m: number; t: number; p: number; salt: Bytes; wrapped: Bytes };
type SshSlot = { type: "ssh"; keyType: string; fingerprint: string; salt: Bytes; wrapped: Bytes };
type Slot = PwSlot | SshSlot;

type ParsedFile = {
  mode: "lines" | "blob";
  ws: boolean;
  pad: number;
  chunk: number;
  headerLine: string;
  slots: Slot[];
  slotLines: string[];
  seal: Bytes | null;
  body: Bytes;
};

function parseKdf(profile: string | KdfParams | undefined): KdfParams {
  let k: KdfParams;
  if (profile === undefined || profile === "default") k = { m: 65536, t: 3, p: 4 };
  else if (profile === "strong") k = { m: 1048576, t: 4, p: 4 };
  else if (typeof profile === "string") {
    const mt = /^m=([1-9][0-9]{0,7}),t=([1-9][0-9]?),p=([1-9][0-9]?)$/.exec(profile);
    if (!mt) throw new SsencError("USAGE", "invalid kdf profile '" + profile + "' (use default, strong or m=..,t=..,p=..)");
    k = { m: Number(mt[1]), t: Number(mt[2]), p: Number(mt[3]) };
  } else k = profile;
  if (!kdfInRange(k)) throw new SsencError("USAGE", "kdf parameters out of range (8*p <= m <= 4194304, 1 <= t <= 64, 1 <= p <= 16)");
  return k;
}

function kdfInRange(k: KdfParams): boolean {
  return Number.isInteger(k.m) && Number.isInteger(k.t) && Number.isInteger(k.p) &&
    k.p >= 1 && k.p <= 16 && k.t >= 1 && k.t <= 64 && k.m >= 8 * k.p && k.m <= 4194304;
}

function headerLineFor(mode: "lines" | "blob", ws: boolean, pad: number, chunk: number): string {
  return mode === "lines" ? "#ssenc1 lines ws=" + (ws ? 1 : 0) + " pad=" + pad : "#ssenc1 blob chunk=" + chunk;
}

function slotLine(s: Slot): string {
  if (s.type === "pw") {
    return "#slot pw argon2id m=" + s.m + ",t=" + s.t + ",p=" + s.p + " " + b64urlEncode(s.salt) + " " + b64urlEncode(s.wrapped);
  }
  return "#slot ssh " + s.keyType + " " + s.fingerprint + " " + b64urlEncode(s.salt) + " " + b64urlEncode(s.wrapped);
}

function decodeField(s: string, len: number, what: string): Bytes {
  const b = b64urlDecode(s);
  if (!b || b.length !== len) throw new SsencError("MALFORMED", "invalid " + what + " in header");
  return b;
}

function parseSlotLine(line: string): Slot {
  let m = /^#slot pw argon2id m=([1-9][0-9]{0,7}),t=([1-9][0-9]?),p=([1-9][0-9]?) ([A-Za-z0-9_-]+) ([A-Za-z0-9_-]+)$/.exec(line);
  if (m) {
    const slot: PwSlot = {
      type: "pw", m: Number(m[1]), t: Number(m[2]), p: Number(m[3]),
      salt: decodeField(m[4], 16, "password slot salt"), wrapped: decodeField(m[5], 48, "wrapped key"),
    };
    if (!kdfInRange(slot)) throw new SsencError("MALFORMED", "argon2id parameters out of range in header");
    return slot;
  }
  m = /^#slot ssh (ssh-ed25519|ssh-rsa) (SHA256:[A-Za-z0-9+\/]{43}) ([A-Za-z0-9_-]+) ([A-Za-z0-9_-]+)$/.exec(line);
  if (m) {
    return {
      type: "ssh", keyType: m[1], fingerprint: m[2],
      salt: decodeField(m[3], 32, "ssh slot salt"), wrapped: decodeField(m[4], 48, "wrapped key"),
    };
  }
  throw new SsencError("MALFORMED", "unrecognised slot line in header");
}

function parseFile(input: Bytes): ParsedFile {
  let pos = 0;
  const peekLine = (): { text: string; next: number } | null => {
    if (pos >= input.length) return null;
    let end = input.indexOf(10, pos);
    const next = end < 0 ? input.length : end + 1;
    if (end < 0) end = input.length;
    if (end > pos && input[end - 1] === 13) end--;
    if (end - pos > 1024) return { text: ascii(input.subarray(pos, pos + 16)), next };
    return { text: ascii(input.subarray(pos, end)), next };
  };
  const first = peekLine();
  if (!first || !first.text.startsWith("#ssenc1 ")) throw new SsencError("MALFORMED", "not an ssenc1 file (missing '#ssenc1' header)");
  const out: ParsedFile = {
    mode: "lines", ws: true, pad: 0, chunk: 0, headerLine: first.text,
    slots: [], slotLines: [], seal: null, body: input.subarray(0, 0) as Bytes,
  };
  let m = /^#ssenc1 lines ws=([01]) pad=(0|[1-9][0-9]{0,3})$/.exec(first.text);
  if (m) {
    out.ws = m[1] === "1";
    out.pad = Number(m[2]);
    if (out.pad > 4096) throw new SsencError("MALFORMED", "pad out of range in header");
  } else {
    m = /^#ssenc1 blob chunk=([1-9][0-9]{0,6})$/.exec(first.text);
    if (!m) throw new SsencError("MALFORMED", "invalid '#ssenc1' header line");
    out.mode = "blob";
    out.chunk = Number(m[1]);
    if (out.chunk > 1048576) throw new SsencError("MALFORMED", "chunk out of range in header");
  }
  pos = first.next;
  for (;;) {
    const line = peekLine();
    if (!line) break;
    if (line.text.startsWith("#slot ")) {
      if (out.seal) throw new SsencError("MALFORMED", "slot line after seal line");
      out.slots.push(parseSlotLine(line.text));
      out.slotLines.push(line.text);
    } else if (line.text.startsWith("#seal ")) {
      if (out.seal || out.mode !== "lines") throw new SsencError("MALFORMED", "unexpected seal line");
      if (!/^#seal [A-Za-z0-9_-]+$/.test(line.text)) throw new SsencError("MALFORMED", "invalid seal line");
      out.seal = decodeField(line.text.slice(6), 32, "seal");
    } else break;
    pos = line.next;
  }
  if (out.slots.length === 0) throw new SsencError("MALFORMED", "header has no key slots");
  out.body = input.subarray(pos) as Bytes;
  return out;
}


// ---------------------------------------------------------------------------------------
// ssh key handling shared by both builds (SPEC.md section 2.3)
// ---------------------------------------------------------------------------------------

/**
 * Produces the signature blob for `data` with the key `publicKeyBlob`.
 * Must return string(algorithm) || string(signature) exactly as an ssh-agent does; for an
 * ssh-rsa key the algorithm must be rsa-sha2-512.
 */
type SshSigner = (publicKeyBlob: Uint8Array, data: Uint8Array) => Promise<Uint8Array>;

const SSH_NAMESPACE = "ssenc-v1@stopsopa";

function sshReadString(b: Uint8Array, off: number): { value: Uint8Array; next: number } | null {
  if (off + 4 > b.length) return null;
  const len = ((b[off] << 24) | (b[off + 1] << 16) | (b[off + 2] << 8) | b[off + 3]) >>> 0;
  if (off + 4 + len > b.length) return null;
  return { value: b.subarray(off + 4, off + 4 + len), next: off + 4 + len };
}

function sshKeyType(blob: Uint8Array): string {
  const s = sshReadString(blob, 0);
  if (!s) throw new SsencError("ENV", "invalid ssh public key");
  return ascii(s.value);
}

function sshRequireSupported(keyType: string): void {
  if (keyType !== "ssh-ed25519" && keyType !== "ssh-rsa") {
    throw new SsencError("ENV", "unsupported ssh key type '" + keyType +
      "': only ssh-ed25519 and ssh-rsa give deterministic signatures");
  }
}

/** Parses one line of an OpenSSH public key file ("type base64 [comment]"). */
function sshParsePublicKey(text: string): Bytes {
  for (const line of text.split(/\r?\n/)) {
    const parts = line.trim().split(/\s+/);
    if (parts.length >= 2 && /^(ssh-|ecdsa-|sk-)/.test(parts[0])) {
      const blob = b64stdDecode(parts[1]);
      if (blob && sshKeyType(blob) === parts[0]) return blob;
    }
  }
  throw new SsencError("ENV", "not an OpenSSH public key");
}

async function sshFingerprint(blob: Uint8Array): Promise<string> {
  return "SHA256:" + b64stdEncodeNoPad(await sha256(blob));
}

async function sshSignedData(salt: Uint8Array): Promise<Bytes> {
  const message = concatBytes(utf8("ssenc1 ssh slot"), salt);
  return concatBytes(utf8("SSHSIG"), sshString(utf8(SSH_NAMESPACE)), sshString(new Uint8Array(0)),
    sshString(utf8("sha512")), sshString(await sha512(message)));
}

async function sshKek(blob: Uint8Array, salt: Uint8Array, signer: SshSigner): Promise<Bytes> {
  const keyType = sshKeyType(blob);
  sshRequireSupported(keyType);
  const data = await sshSignedData(salt);
  let sig: Uint8Array;
  try {
    sig = await signer(blob, data);
  } catch (e) {
    if (e instanceof SsencError) throw e;
    throw new SsencError("ENV", "ssh signer failed: " + (e instanceof Error ? e.message : String(e)));
  }
  const alg = sshReadString(sig, 0);
  const raw = alg ? sshReadString(sig, alg.next) : null;
  const expected = keyType === "ssh-rsa" ? "rsa-sha2-512" : "ssh-ed25519";
  if (!alg || !raw || raw.next !== sig.length || ascii(alg.value) !== expected) {
    throw new SsencError("ENV", "ssh signer returned an unexpected signature (need " + expected + ")");
  }
  return hkdf32(sig, salt, "ssenc1/ssh-kek");
}


// ---------------------------------------------------------------------------------------
// ssh-agent is unreachable from a browser: ssh keys need a caller-supplied `signer`.
// ---------------------------------------------------------------------------------------

const NO_AGENT = "ssh-agent is not reachable from a browser: pass 'publicKey' and a 'signer' function with the ssh key";

async function agentSign(_socketPath: string | undefined, _blob: Uint8Array, _data: Uint8Array): Promise<Bytes> {
  throw new SsencError("ENV", NO_AGENT);
}

async function agentFindKey(_socketPath: string | undefined, _fingerprint: string): Promise<Bytes> {
  throw new SsencError("ENV", NO_AGENT);
}



// ---------------------------------------------------------------------------------------
// public types
// ---------------------------------------------------------------------------------------

type PasswordKey = { type: "password"; password: string | Uint8Array };

type SshKey = {
  type: "ssh";
  /** Content of an OpenSSH public key file ("ssh-ed25519 AAAA... comment"). */
  publicKey?: string;
  /** "SHA256:..." fingerprint of a key loaded in ssh-agent; used when publicKey is not given. */
  fingerprint?: string;
  /** Path of the agent socket; default is $SSH_AUTH_SOCK (Node.js build only). */
  agentSocket?: string;
  /** Replaces ssh-agent as the source of the signature; required in the browser build. */
  signer?: SshSigner;
};

type Key = PasswordKey | SshKey;

type EncryptOptions = {
  /** "lines" (default) encrypts line by line; "blob" encrypts the input as a whole. */
  mode?: "lines" | "blob";
  /** Lines mode: keep leading and trailing spaces/tabs of every line in clear. Default true. */
  preserveWhitespace?: boolean;
  /** Lines mode: pad every line to a multiple of this many bytes; 0 disables. Default 16. */
  pad?: number;
  /** Blob mode: chunk size in bytes. Default 65536. */
  chunk?: number;
  /** Argon2id cost for password slots: "default", "strong", "m=..,t=..,p=.." or an object. */
  kdf?: string | KdfParams;
  /** Previous encrypted version: its data key and slots are reused, so unchanged lines stay identical. */
  previous?: string | Uint8Array;
  /** Lines mode: add a MAC over the whole file. Default false. */
  seal?: boolean;
};

type RekeyOptions = {
  /** true (default): re-encrypt everything under a new data key. false: only rewrap the data key. */
  rotateDataKey?: boolean;
  kdf?: string | KdfParams;
};

type SlotInfo =
  | { type: "pw"; kdf: "argon2id"; m: number; t: number; p: number }
  | { type: "ssh"; keyType: string; fingerprint: string };

type InspectResult =
  | { format: "ssenc1"; mode: "lines"; ws: boolean; pad: number; seal: boolean; slots: SlotInfo[] }
  | { format: "ssenc1"; mode: "blob"; chunk: number; slots: SlotInfo[] };

// ---------------------------------------------------------------------------------------
// key slots
// ---------------------------------------------------------------------------------------

const SLOT_AD: Bytes = utf8("ssenc1/slot");

function passwordBytes(key: PasswordKey): Bytes {
  const pw = toBytes(key.password);
  if (pw.length === 0) throw new SsencError("USAGE", "password must not be empty");
  return pw;
}

// Optional in-memory cache of Argon2id results. Off by default. An interactive page that
// re-encrypts on every keystroke would otherwise pay the full Argon2id cost each time.
// While enabled, derived keys stay in memory for as long as they are cached.
let kdfCacheSize = 0;
const kdfCache = new Map<string, Bytes>();

/** Keeps up to `entries` Argon2id results in memory (0, the default, disables and clears the cache). */
function setKdfCacheSize(entries: number): void {
  kdfCacheSize = Math.max(0, Math.floor(entries));
  while (kdfCache.size > kdfCacheSize) kdfCache.delete(kdfCache.keys().next().value as string);
}

async function passwordKek(pw: Uint8Array, salt: Uint8Array, m: number, t: number, p: number): Promise<Bytes> {
  if (kdfCacheSize === 0) return argon2id(pw, salt, m, t, p, 32);
  const id = b64urlEncode(await sha256(concatBytes(u64be(pw.length), pw, u64be(salt.length), salt, utf8(m + "," + t + "," + p))));
  let kek = kdfCache.get(id);
  if (kek) {
    kdfCache.delete(id);
  } else {
    kek = argon2id(pw, salt, m, t, p, 32);
    if (kdfCache.size >= kdfCacheSize) kdfCache.delete(kdfCache.keys().next().value as string);
  }
  kdfCache.set(id, kek);
  return kek;
}

type ResolvedSsh = { blob: Bytes; keyType: string; fingerprint: string; signer: SshSigner };

async function resolveSsh(key: SshKey): Promise<ResolvedSsh> {
  let blob: Bytes;
  if (key.publicKey !== undefined) blob = sshParsePublicKey(key.publicKey);
  else if (key.fingerprint !== undefined) blob = await agentFindKey(key.agentSocket, key.fingerprint);
  else throw new SsencError("USAGE", "ssh key needs 'publicKey' or 'fingerprint'");
  const keyType = sshKeyType(blob);
  sshRequireSupported(keyType);
  const signer: SshSigner = key.signer ?? ((b, d) => agentSign(key.agentSocket, b, d));
  return { blob, keyType, fingerprint: await sshFingerprint(blob), signer };
}

async function wrapDek(kek: Uint8Array, dek: Uint8Array): Promise<Bytes> {
  return sivEncrypt(await sivKey(kek, "wrap"), SLOT_AD, dek);
}

async function makeSlots(keys: Key[], dek: Uint8Array, kdf: KdfParams): Promise<string[]> {
  if (keys.length === 0) throw new SsencError("USAGE", "at least one key is required");
  const lines: string[] = [];
  for (const key of keys) {
    if (key.type !== "password") continue;
    const salt = randomBytes(16);
    const kek = await passwordKek(passwordBytes(key), salt, kdf.m, kdf.t, kdf.p);
    lines.push(slotLine({ type: "pw", m: kdf.m, t: kdf.t, p: kdf.p, salt, wrapped: await wrapDek(kek, dek) }));
  }
  for (const key of keys) {
    if (key.type !== "ssh") continue;
    const r = await resolveSsh(key);
    const salt = randomBytes(32);
    const kek = await sshKek(r.blob, salt, r.signer);
    lines.push(slotLine({ type: "ssh", keyType: r.keyType, fingerprint: r.fingerprint, salt, wrapped: await wrapDek(kek, dek) }));
  }
  return lines;
}

async function tryUnwrap(kek: Uint8Array, slot: Slot): Promise<Bytes | null> {
  try {
    return await sivDecrypt(await sivKey(kek, "wrap"), SLOT_AD, slot.wrapped);
  } catch (e) {
    if (e instanceof SsencError && e.kind === "AUTH") return null;
    throw e;
  }
}

/** Returns the data key, or null when no slot opens with this key. */
async function openWith(file: ParsedFile, key: Key): Promise<Bytes | null> {
  if (key.type === "password") {
    const pw = passwordBytes(key);
    for (const slot of file.slots) {
      if (slot.type !== "pw") continue;
      const dek = await tryUnwrap(await passwordKek(pw, slot.salt, slot.m, slot.t, slot.p), slot);
      if (dek) return dek;
    }
    return null;
  }
  const r = await resolveSsh(key);
  for (const slot of file.slots) {
    if (slot.type !== "ssh" || slot.fingerprint !== r.fingerprint) continue;
    const dek = await tryUnwrap(await sshKek(r.blob, slot.salt, r.signer), slot);
    if (dek) return dek;
  }
  return null;
}

async function openOrFail(file: ParsedFile, keys: Key[]): Promise<Bytes> {
  if (keys.length === 0) throw new SsencError("USAGE", "at least one key is required");
  for (const key of keys) {
    const dek = await openWith(file, key);
    if (dek) return dek;
  }
  throw new SsencError("AUTH", "no key slot could be opened with the given key");
}

// ---------------------------------------------------------------------------------------
// lines mode (SPEC.md section 3)
// ---------------------------------------------------------------------------------------

function isWs(c: number): boolean {
  return c === 32 || c === 9;
}

/** Calls fn(contentStart, contentEnd, lineEnd) for every line; lineEnd includes the terminator. */
function eachLine(data: Uint8Array, fn: (start: number, end: number, next: number) => void): void {
  let pos = 0;
  while (pos < data.length) {
    const lf = data.indexOf(10, pos);
    if (lf < 0) {
      fn(pos, data.length, data.length);
      return;
    }
    fn(pos, lf > pos && data[lf - 1] === 13 ? lf - 1 : lf, lf + 1);
    pos = lf + 1;
  }
}

function padLine(x: Uint8Array, pad: number): Uint8Array {
  if (pad === 0) return x;
  const out = new Uint8Array((Math.floor(x.length / pad) + 1) * pad);
  out.set(x);
  out[x.length] = 0x80;
  return out;
}

function unpadLine(x: Uint8Array, pad: number): Uint8Array {
  if (pad === 0) return x;
  let n = x.length;
  while (n > 0 && x[n - 1] === 0) n--;
  if (n === 0 || x[n - 1] !== 0x80) throw new SsencError("MALFORMED", "invalid line padding");
  return x.subarray(0, n - 1);
}

const EMPTY: Bytes = new Uint8Array(0);

async function encryptLines(dek: Uint8Array, ws: boolean, pad: number, plain: Uint8Array): Promise<Bytes> {
  const key = await sivKey(dek, "line");
  const spans: number[] = [];
  eachLine(plain, (s, e, n) => spans.push(s, e, n));
  const parts: Uint8Array[] = [];
  for (let i = 0; i < spans.length; i += 3) {
    let s = spans[i];
    let e = spans[i + 1];
    const next = spans[i + 2];
    const lineStart = s;
    const lineEnd = e;
    if (ws) {
      while (s < e && isWs(plain[s])) s++;
      while (e > s && isWs(plain[e - 1])) e--;
      if (s === e) {
        parts.push(plain.subarray(lineStart, next));
        continue;
      }
    }
    const token = b64urlEncode(await sivEncrypt(key, EMPTY, padLine(plain.subarray(s, e), pad)));
    parts.push(plain.subarray(lineStart, s), utf8(token), plain.subarray(e, lineEnd), plain.subarray(lineEnd, next));
  }
  return concatBytes(...parts);
}

async function decryptLines(dek: Uint8Array, pad: number, body: Uint8Array): Promise<Bytes> {
  const key = await sivKey(dek, "line");
  const spans: number[] = [];
  eachLine(body, (s, e, n) => spans.push(s, e, n));
  const parts: Uint8Array[] = [];
  for (let i = 0; i < spans.length; i += 3) {
    let s = spans[i];
    let e = spans[i + 1];
    const next = spans[i + 2];
    const lineStart = s;
    const lineEnd = e;
    while (s < e && isWs(body[s])) s++;
    while (e > s && isWs(body[e - 1])) e--;
    if (s === e) {
      parts.push(body.subarray(lineStart, next));
      continue;
    }
    const raw = b64urlDecodeBytes(body.subarray(s, e));
    if (!raw || raw.length < 16) throw new SsencError("MALFORMED", "line " + (i / 3 + 1) + " is not a valid encrypted line");
    const plain = unpadLine(await sivDecrypt(key, EMPTY, raw), pad);
    parts.push(body.subarray(lineStart, s), plain, body.subarray(e, lineEnd), body.subarray(lineEnd, next));
  }
  return concatBytes(...parts);
}

async function sealFor(dek: Uint8Array, headerLine: string, body: Uint8Array): Promise<Bytes> {
  const k = await hkdf32(dek, null, "ssenc1/seal");
  return hmacSha256(k, concatBytes(utf8(headerLine), new Uint8Array([10]), body));
}

// ---------------------------------------------------------------------------------------
// blob mode (SPEC.md section 4)
// ---------------------------------------------------------------------------------------

function blobAd(index: number, final: boolean): Bytes {
  return concatBytes(u64be(index), new Uint8Array([final ? 1 : 0]));
}

async function encryptBlob(dek: Uint8Array, chunk: number, plain: Uint8Array): Promise<Bytes> {
  const key = await sivKey(dek, "blob");
  const records: Uint8Array[] = [];
  const count = Math.max(1, Math.ceil(plain.length / chunk));
  for (let i = 0; i < count; i++) {
    records.push(await sivEncrypt(key, blobAd(i, i === count - 1), plain.subarray(i * chunk, (i + 1) * chunk)));
  }
  const b64 = b64urlEncode(concatBytes(...records));
  const lines: string[] = [];
  for (let i = 0; i < b64.length; i += 76) lines.push(b64.slice(i, i + 76) + "\n");
  return utf8(lines.join(""));
}

async function decryptBlob(dek: Uint8Array, chunk: number, body: Uint8Array): Promise<Bytes> {
  const compact = new Uint8Array(body.length);
  let n = 0;
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (c !== 10 && c !== 13 && c !== 32 && c !== 9) compact[n++] = c;
  }
  const raw = b64urlDecodeBytes(compact.subarray(0, n));
  if (!raw || raw.length === 0) throw new SsencError("MALFORMED", "blob body is not valid base64url");
  const key = await sivKey(dek, "blob");
  const rec = chunk + 16;
  const count = Math.ceil(raw.length / rec);
  const parts: Uint8Array[] = [];
  for (let i = 0; i < count; i++) {
    parts.push(await sivDecrypt(key, blobAd(i, i === count - 1), raw.subarray(i * rec, (i + 1) * rec)));
  }
  return concatBytes(...parts);
}

// ---------------------------------------------------------------------------------------
// operations (SPEC.md section 5)
// ---------------------------------------------------------------------------------------

type Layout = { mode: "lines" | "blob"; ws: boolean; pad: number; chunk: number; seal: boolean };

function checkLayout(l: Layout): void {
  if (l.mode !== "lines" && l.mode !== "blob") throw new SsencError("USAGE", "mode must be 'lines' or 'blob'");
  if (!Number.isInteger(l.pad) || l.pad < 0 || l.pad > 4096) throw new SsencError("USAGE", "pad must be an integer from 0 to 4096");
  if (!Number.isInteger(l.chunk) || l.chunk < 1 || l.chunk > 1048576) throw new SsencError("USAGE", "chunk must be an integer from 1 to 1048576");
  if (l.seal && l.mode !== "lines") throw new SsencError("USAGE", "seal is only available in lines mode");
}

async function assemble(dek: Uint8Array, slotLines: string[], l: Layout, plain: Uint8Array): Promise<string> {
  const headerLine = headerLineFor(l.mode, l.ws, l.pad, l.chunk);
  const body = l.mode === "lines" ? await encryptLines(dek, l.ws, l.pad, plain) : await encryptBlob(dek, l.chunk, plain);
  let head = headerLine + "\n" + slotLines.map((s) => s + "\n").join("");
  if (l.seal) head += "#seal " + b64urlEncode(await sealFor(dek, headerLine, body)) + "\n";
  return head + ascii(body);
}

async function decryptParsed(file: ParsedFile, dek: Uint8Array): Promise<Bytes> {
  if (file.seal && !constantTimeEqual(file.seal, await sealFor(dek, file.headerLine, file.body))) {
    throw new SsencError("AUTH", "seal does not match: lines were added, removed, reordered or modified");
  }
  return file.mode === "lines" ? decryptLines(dek, file.pad, file.body) : decryptBlob(dek, file.chunk, file.body);
}

function keyList(key: Key | Key[]): Key[] {
  return Array.isArray(key) ? key : [key];
}

/** Encrypts bytes (or a string, as UTF-8) to ssenc1 ASCII text. */
async function encrypt(input: Uint8Array | string, key: Key | Key[], options: EncryptOptions = {}): Promise<string> {
  const plain = toBytes(input);
  const keys = keyList(key);
  if (options.previous !== undefined) {
    const prev = parseFile(toBytes(options.previous));
    const dek = await openOrFail(prev, keys);
    const mode = options.mode ?? prev.mode;
    const layout: Layout = {
      mode,
      ws: options.preserveWhitespace ?? (prev.mode === "lines" ? prev.ws : true),
      pad: options.pad ?? (prev.mode === "lines" ? prev.pad : 16),
      chunk: options.chunk ?? (prev.mode === "blob" ? prev.chunk : 65536),
      seal: options.seal ?? (mode === "lines" && prev.seal !== null),
    };
    checkLayout(layout);
    return assemble(dek, prev.slotLines, layout, plain);
  }
  const layout: Layout = {
    mode: options.mode ?? "lines",
    ws: options.preserveWhitespace ?? true,
    pad: options.pad ?? 16,
    chunk: options.chunk ?? 65536,
    seal: options.seal ?? false,
  };
  checkLayout(layout);
  const kdf = parseKdf(options.kdf);
  const dek = randomBytes(32);
  return assemble(dek, await makeSlots(keys, dek, kdf), layout, plain);
}

/** Decrypts ssenc1 text and returns the original bytes. */
async function decrypt(input: Uint8Array | string, key: Key): Promise<Bytes> {
  const file = parseFile(toBytes(input));
  return decryptParsed(file, await openOrFail(file, [key]));
}

/** Like decrypt, for input that was text: returns it as a string (UTF-8). */
async function decryptToString(input: Uint8Array | string, key: Key): Promise<string> {
  return new TextDecoder().decode(await decrypt(input, key));
}

/** Replaces the keys of an encrypted text. */
async function rekey(input: Uint8Array | string, oldKey: Key, newKey: Key | Key[], options: RekeyOptions = {}): Promise<string> {
  const file = parseFile(toBytes(input));
  const dek = await openOrFail(file, [oldKey]);
  const kdf = parseKdf(options.kdf);
  if (options.rotateDataKey === false) {
    const slots = await makeSlots(keyList(newKey), dek, kdf);
    let head = file.headerLine + "\n" + slots.map((s) => s + "\n").join("");
    if (file.seal) head += "#seal " + b64urlEncode(file.seal) + "\n";
    return head + ascii(file.body);
  }
  const plain = await decryptParsed(file, dek);
  const layout: Layout = {
    mode: file.mode, ws: file.ws, pad: file.mode === "lines" ? file.pad : 16,
    chunk: file.mode === "blob" ? file.chunk : 65536, seal: file.seal !== null,
  };
  const newDek = randomBytes(32);
  return assemble(newDek, await makeSlots(keyList(newKey), newDek, kdf), layout, plain);
}

/** Describes an encrypted text without needing a key. */
function inspect(input: Uint8Array | string): InspectResult {
  const file = parseFile(toBytes(input));
  const slots: SlotInfo[] = file.slots.map((s) => s.type === "pw"
    ? { type: "pw", kdf: "argon2id", m: s.m, t: s.t, p: s.p }
    : { type: "ssh", keyType: s.keyType, fingerprint: s.fingerprint });
  if (file.mode === "lines") {
    return { format: "ssenc1", mode: "lines", ws: file.ws, pad: file.pad, seal: file.seal !== null, slots };
  }
  return { format: "ssenc1", mode: "blob", chunk: file.chunk, slots };
}

